// ================= EDIT YOUR SETTINGS HERE =================
// Negative prompt used by the Wan 2.2 Space (tells the model what to avoid)
const WAN_NEGATIVE = '色调艳丽, 过曝, 静态, 细节模糊不清, 字幕, 风格, 作品, 画作, 画面, 静止, 整体发灰, 最差质量, 低质量, JPEG压缩残留, 丑陋的, 残缺的, 多余的手指, 画得不好的手部, 画得不好的脸部, 畸形的, 毁容的, 形态畸形的肢体, 手指融合, 静止不动的画面, 杂乱的背景, 三条腿, 背景人很多, 倒着走';

const WAN_FAST = {
  name: 'Wan 2.2 14B Fast (free HF Space)',
  space_url: 'https://zerogpu-aoti-wan2-2-fp8da-aoti-faster.hf.space',
  api_name: 'generate_video',
  // Must match the order of the Space's inputs (see "Use via API" at the bottom of the Space page).
  // __IMAGE__ and __PROMPT__ are filled in automatically.
  // [image, prompt, steps, negative_prompt, duration_seconds, guidance, guidance_2, seed, randomize_seed]
  data: ['__IMAGE__', '__PROMPT__', 4, WAN_NEGATIVE, 3.5, 1, 1, 42, true],
};

const settings = {
  daily_limit_per_user: 2,   // videos per Telegram user per day (0 = unlimited)
  admin_user_ids: [],        // put YOUR Telegram user ID here, e.g. [123456789] = no limit for you
  timezone: 'Asia/Kolkata',  // when the daily count resets
  providers: [
    WAN_FAST,                                        // primary
    { ...WAN_FAST, name: 'Wan 2.2 14B Fast (retry)' } // fallback: retries once if the Space was busy.
                                                      // Swap in another Space here if you like.
  ],
};
// ===========================================================
return [{ json: { ...$json, settings } }];

const msg = $json.message ?? {};
const MAX_BYTES = 20 * 1024 * 1024; // Telegram bots can only download files up to 20 MB

const DEFAULT_PROMPT = 'make this image come alive, subtle realistic movement, slow smooth camera motion, natural lighting, cinematic';
const PRESETS = {
  '/portrait':  'Cinematic slow push-in, natural ambient movement, soft directional lighting shift, gentle micro-movement, shallow depth of field',
  '/landscape': 'Subtle camera pan from left to right, gentle breeze moving background elements, volumetric sunlight, realistic physics',
  '/product':   'Slow smooth orbit around the subject, soft studio key-light reflection, subtle focus rack, steady motion',
};

let fileId = null, mimeType = 'image/jpeg', rejectReason = null;

if (Array.isArray(msg.photo) && msg.photo.length > 0) {
  fileId = msg.photo[msg.photo.length - 1].file_id; // highest resolution
} else if (msg.document?.mime_type?.startsWith('image/')) {
  if ((msg.document.file_size ?? 0) > MAX_BYTES) {
    rejectReason = 'That image is over 20 MB, the most a Telegram bot can download. Please send a smaller file.';
  } else {
    fileId = msg.document.file_id;
    mimeType = msg.document.mime_type;
  }
} else {
  rejectReason = "Send me a photo and I'll turn it into a short video 🎬\n\n" +
    'Add a caption to describe the motion, or start it with /portrait, /landscape or /product.';
}

// Prompt for the MODEL: plain text, never HTML-escaped
const raw = (msg.caption ?? '').replace(/[\u0000-\u001F\u007F]/g, ' ').trim().substring(0, 250);
const [first, ...rest] = raw.split(/\s+/);
const preset = PRESETS[(first ?? '').toLowerCase()];
let prompt;
if (preset) {
  const extra = rest.join(' ').trim();
  prompt = extra ? `${preset}. ${extra}` : preset;
} else {
  prompt = raw || DEFAULT_PROMPT;
}

// Prompt for DISPLAY in Telegram (HTML mode): escaped
const escapeHtml = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

return [{ json: {
  has_image: Boolean(fileId),
  reject_reason: rejectReason,
  file_id: fileId,
  mime_type: mimeType,
  prompt,
  prompt_html: escapeHtml(prompt.substring(0, 300)),
  chat_id: msg.chat?.id,
  user_id: msg.from?.id,
  message_id: msg.message_id,
}}];

// Per-user daily limit, stored in workflow static data.
// Note: static data only persists in PRODUCTION runs (workflow Active), not manual test runs.
const p = $input.first().json;
const s = $('Settings').first().json.settings;
const store = $getWorkflowStaticData('global');

const today = new Date().toLocaleDateString('en-CA', { timeZone: s.timezone });
if (store.usage_day !== today) { store.usage_day = today; store.usage = {}; }

const uid = String(p.user_id);
const used = store.usage[uid] ?? 0;
const isAdmin = (s.admin_user_ids ?? []).map(String).includes(uid);
const allowed = isAdmin || !s.daily_limit_per_user || used < s.daily_limit_per_user;
if (allowed) store.usage[uid] = used + 1;

return [{ json: {
  ...p,
  allowed,
  limit_message: allowed ? null :
    `You've used your ${s.daily_limit_per_user} free videos for today 🌙 Please come back tomorrow!`,
}}];

// Image -> base64 so it can be handed to the sub-workflow. Your bot token never leaves n8n.
const bin = $input.first().binary?.data;
if (!bin) throw new Error('Could not download the image from Telegram');
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const parsed = $('Check Daily Limit').first().json;
const settings = $('Settings').first().json.settings;
const ack = $('Send Ack').first().json;

return [{ json: {
  image_base64: buffer.toString('base64'),
  mime_type: bin.mimeType?.startsWith('image/') ? bin.mimeType : parsed.mime_type,
  prompt: parsed.prompt,
  provider: settings.providers[0],
  chat_id: parsed.chat_id,
  user_id: parsed.user_id,
  ack_message_id: ack.result?.message_id ?? ack.message_id,
}}];

// Primary failed. Quota errors skip the fallback: every HF Space shares the same daily GPU quota.
const job = $('Build Job').first().json;
const s = $('Settings').first().json.settings;
const e = $json.error;
const msg = e == null ? 'Unknown error' : typeof e === 'string' ? e : (e.message ?? JSON.stringify(e));
const fallback = s.providers[1] ?? null;
const isQuota = /quota/i.test(msg);

return [{ json: { ...job, provider: fallback, primary_error: msg, go_fallback: !isQuota && Boolean(fallback) } }];

// Lock metadata BEFORE the binary download replaces $json.
const r = $input.first().json;
if (!r.video_url) throw new Error('Sub-workflow finished without a video_url');
const job = $('Build Job').first().json;
return [{ json: {
  video_url: r.video_url,
  provider: r.provider ?? 'Unknown',
  job_id: r.job_id ?? null,
  chat_id: job.chat_id,
  ack_message_id: job.ack_message_id,
  prompt_html: $('Check Daily Limit').first().json.prompt_html,
}}];

const n = $('Normalize Output').first().json;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const e = $json.error;
const reason = e == null ? 'Upload to Telegram failed or timed out'
  : typeof e === 'string' ? e : (e.message ?? JSON.stringify(e));
const text =
  `<b>⚠️ Video rendered, but sending it to Telegram failed.</b>\n\n` +
  `<b>Reason:</b> ${esc(reason).slice(0, 300)}\n\n` +
  `<a href="${esc(n.video_url)}">Download the video here</a> (temporary link, save it soon).`;
return [{ json: { chat_id: n.chat_id, ack_message_id: n.ack_message_id, text } }];

const job = $('Build Job').first().json;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const toText = (e) => e == null ? null : typeof e === 'string' ? e : (e.message ?? JSON.stringify(e));

const primary = $('Route Primary Error').isExecuted ? $('Route Primary Error').first().json.primary_error : null;
const last = toText($json.error);
const all = [primary, last].filter(Boolean).join(' | ') || 'Unknown error';

// Give the user their daily credit back, since nothing was delivered.
const store = $getWorkflowStaticData('global');
const uid = String(job.user_id);
if (store.usage && store.usage[uid] > 0) store.usage[uid] -= 1;

let text;
if (/quota/i.test(all)) {
  const m = all.match(/try again in ([0-9:]+)/i);
  text = `<b>😴 Free GPU time used up for today</b>\n\n` +
    `The free video engine has run out of its daily GPU time.` +
    (m ? ` It resets in about <b>${esc(m[1])}</b>.` : ' Please try again later.') +
    `\n\nThis attempt was not counted against your daily limit.`;
} else {
  text = `<b>⚠️ Video generation failed</b>\n\n` +
    (primary ? `<b>First try:</b> ${esc(primary).slice(0, 250)}\n` : '') +
    (last && last !== primary ? `<b>Retry:</b> ${esc(last).slice(0, 250)}\n` : '') +
    `\nThe free GPU may be busy. Please try again in a few minutes.`;
}
return [{ json: { chat_id: job.chat_id, ack_message_id: job.ack_message_id, text } }];
